const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const preview=new URLSearchParams(location.search).get('preview')==='1';
const pages=[['inicio','Inicio','index.html'],['unidades','Unidades','unidades.html'],['material','Material de consulta','material.html'],['practicos','Trabajos prácticos','practicos.html'],['proyecto','Proyecto integrador','proyecto.html'],['inet','INET','inet.html'],['movimiento','Hormigón en movimiento','movimiento.html'],['calendario','Calendario','calendario.html'],['galeria','Galería','galeria.html'],['colaboradores','Colaboradores','colaboradores.html'],['contacto','Contacto','contacto.html']];
const key=document.body.dataset.page||'inicio';
const link=(p)=>p+(preview?'?preview=1':'');
const empty=(title,text)=>`<div class="empty"><h3>${E(title)}</h3><p>${E(text)}</p></div>`;
const example=x=>x.example?'<span class="tag">Contenido de ejemplo</span>':'';
const resourceLink=x=>ContentStore.safeLink(x.url)?`<a class="btn secondary" href="${E(ContentStore.safeLink(x.url))}" target="_blank" rel="noopener noreferrer">Abrir material ↗</a>`:'<span class="small">Material por incorporar</span>';
const formatDate=v=>v?new Date(v+'T12:00:00').toLocaleDateString('es-AR',{day:'numeric',month:'long',year:'numeric'}):'Fecha por completar';
let content;
function partnerCategories(){return [['engineer','Estudios de ingeniería','Consultas y contratación de cálculo estructural.'],['concrete','Hormigoneras','Hormigón elaborado, ejecución y visitas técnicas.'],['supplier','Corralones','Materiales y asesoramiento para la obra.']].map(([c,t,d])=>`<article class="card"><div class="partner-photo ${c}" role="img" aria-label="Imagen ilustrativa de ${E(t)}"></div><div class="card-body"><h3>${E(t)}</h3><p>${E(d)}</p><span class="tag">Espacio para futuros colaboradores</span></div></article>`).join('')}
function drawShell(){const s=content.settings;document.getElementById('header').innerHTML=`<a class="skip" href="#main">Saltar al contenido</a><header class="top"><div class="wrap"><a class="brand" href="${link('index.html')}">${E(s.school)}<span class="specialty">${E(s.specialty)}</span></a><div class="utility">${ContentStore.safeLink(s.portal)?`<a class="portal" href="${E(ContentStore.safeLink(s.portal))}">← Volver al portal</a>`:''}<a href="admin.html">Administración ↗</a></div></div></header><nav class="nav" aria-label="Navegación principal"><div class="wrap">${pages.map(([k,t,p])=>`<a href="${link(p)}" ${key===k?'aria-current="page"':''}>${t}</a>`).join('')}</div></nav>${preview?'<div class="notice">Vista previa del borrador en este navegador. <a href="admin.html">Volver al editor</a></div>':''}`;
document.getElementById('footer').innerHTML=`<footer class="footer"><div class="wrap"><span><strong>${E(s.school)}</strong> · ${E(s.siteName)}</span><div class="footer-links"><a href="${link('contacto.html')}">Contacto</a>${ContentStore.safeLink(s.instagram)?`<a href="${E(ContentStore.safeLink(s.instagram))}" target="_blank" rel="noopener noreferrer">Instagram ↗</a>`:'<span class="muted">Instagram · próximamente</span>'}<a href="admin.html">Administración</a></div></div></footer>`}
function head(k){const p=content.pages[k];return `<section class="page-head"><div class="wrap"><p class="eyebrow">${E(content.settings.school)} · ${E(content.settings.specialty)}</p><h1>${E(p.title)}</h1><p class="muted">${E(p.description)}</p></div></section>`}
function home(){const s=content.settings;const topic=[...content.topics].sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];return `<section class="hero"><div class="wrap"><h1>${E(s.siteName)}</h1><h2>${E(s.tagline)}</h2><p>${E(s.intro)}</p><div class="actions"><a class="btn" href="${link('unidades.html')}">Explorar unidades →</a><a class="btn secondary" href="${link('proyecto.html')}">Ver proyecto integrador</a></div></div></section><section class="section"><div class="wrap"><div class="home-top"><article class="card topic"><p class="eyebrow">Libro de temas</p><h2>Esta semana estamos trabajando</h2>${topic?`<h3>${E(topic.title)}</h3><p class="muted">${E(topic.description)}</p><div class="actions">${ContentStore.safeLink(topic.url)?resourceLink(topic):''}<a class="btn secondary" href="${link('libro.html')}">Historial de clases →</a></div>${example(topic)}`:empty('El próximo tema empieza acá','El docente incorporará los contenidos trabajados en cada clase.')}</article><aside class="card"><div class="card-body"><h3>Próximas fechas</h3>${content.events.length?content.events.filter(x=>!x.date||x.date>=new Date().toISOString().slice(0,10)).sort((a,b)=>(a.date||'').localeCompare(b.date||'')).slice(0,3).map(x=>`<p><span class="date">${E(formatDate(x.date))}</span><br>${E(x.title)}</p>`).join('')||'<p>No hay próximas fechas cargadas.</p>':'<p>Las entregas y evaluaciones aparecerán aquí cuando se carguen.</p>'}<a href="${link('calendario.html')}">Ver calendario →</a></div></aside></div></div></section><section class="section"><div class="wrap"><div class="grid">${[['material','Material de consulta','Bibliografía, reglamentos y apuntes'],['movimiento','Hormigón en movimiento','Videos y animaciones para comprender'],['proyecto','Proyecto integrador','Planos, detalles y síntesis de cálculo']].map(([k,t,d])=>`<article class="card"><div class="card-body"><a class="card-link" href="${link(k+'.html')}">${t}<span aria-hidden="true">→</span></a><p>${d}</p><div class="thumb ${k}" role="img" aria-label="Ilustración de ${E(t)}"></div></div></article>`).join('')}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Vinculación profesional</p><h2>Red de colaboradores</h2><p class="muted">Un puente entre el aula y la práctica profesional.</p></div><a href="${link('colaboradores.html')}">Explorar la red →</a></div><div class="grid">${partnerCategories()}</div></div></section><section class="section"><div class="wrap"><div class="callout"><div><p class="eyebrow">Galería</p><h2>Del plano a la Expo</h2><p class="muted">Trabajos CAD, plantas de techo, detalles y maquetas de los estudiantes.</p></div><a class="btn" href="${link('galeria.html')}">Ver trabajos →</a></div></div></section>`}
function materials(k){const xs=k==='unidades'?content.units:content.resources.filter(x=>x.page===k);return head(k)+`<section class="section"><div class="wrap">${xs.length?`<label class="search">Buscar en esta página<input id="search" type="search" placeholder="Escribí un tema…"></label><div class="grid" id="resource-grid">${xs.map(x=>`<article class="card searchable" data-search="${E((x.title+' '+x.description).toLowerCase())}"><div class="card-body">${example(x)}<h3>${E(x.title)}</h3><p>${E(x.description)}</p>${resourceLink(x)}</div></article>`).join('')}</div><p id="search-empty" hidden class="muted">No hay coincidencias.</p>`:empty('Este espacio está listo para cargar contenido',{'material':'Podrás incorporar apuntes, bibliografía y enlaces a reglamentos.','practicos':'Podrás incorporar consignas, archivos y fechas de entrega.','proyecto':'Podrás incorporar el proyecto, sus etapas, planos y detalles.','inet':'Podrás reunir aquí los enlaces y materiales de INET.','movimiento':'Podrás incorporar enlaces a videos y animaciones.'}[k])}</div></section>`}
function book(){return head('libro')+`<section class="section"><div class="wrap"><div class="timeline">${content.topics.length?[...content.topics].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(x=>`<article class="card"><div class="card-body"><p class="date">${E(formatDate(x.date))}</p>${example(x)}<h3>${E(x.title)}</h3><p>${E(x.description)}</p>${resourceLink(x)}</div></article>`).join(''):empty('Todavía no hay clases registradas','El libro de temas se irá completando con el recorrido de la materia.')}</div></div></section>`}
function calendar(){return head('calendario')+`<section class="section"><div class="wrap"><div class="list">${content.events.length?[...content.events].sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(x=>`<article class="card"><div class="card-body"><div><p class="date">${E(formatDate(x.date))}</p><h3>${E(x.title)}</h3><p>${E(x.description)}</p>${example(x)}</div>${ContentStore.safeLink(x.url)?resourceLink(x):''}</div></article>`).join(''):empty('Todavía no hay fechas cargadas','Cuando se publiquen entregas, evaluaciones o visitas técnicas, aparecerán aquí y en el inicio.')}</div></div></section>`}
function gallery(){return head('galeria')+`<section class="section"><div class="wrap"><div class="filters" role="group" aria-label="Filtrar imágenes">${['Todas','Planos y CAD','Maquetas','Expo'].map((t,i)=>`<button class="filter" aria-pressed="${!i}" data-category="${E(t)}">${t}</button>`).join('')}</div><div class="grid" id="gallery-grid">${content.gallery.map(x=>`<article class="card gallery-card" data-category="${E(x.category)}"><button class="gallery-btn" data-image="${E(x.id)}" aria-label="Ampliar ${E(x.title)}"><img src="${E(ContentStore.safeImage(x.image))}" alt="${E(x.title)}" loading="lazy"></button><div class="card-body"><span class="tag">${E(x.category)}</span><h3>${E(x.title)}</h3><p>${E(x.description)}</p><span class="small">${E([x.course,x.year].filter(Boolean).join(' · '))}</span></div></article>`).join('')}</div><div id="gallery-empty" ${content.gallery.length?'hidden':''}>${empty('Las primeras imágenes empiezan acá','Espacio reservado para capturas CAD, plantas de techo, detalles, maquetas y fotografías de la Expo. Las imágenes se cargarán desde la administración.')}</div></div></section><dialog class="lightbox" id="lightbox"><div class="lightbox-head"><h3 id="light-title"></h3><button class="mini" id="light-close" aria-label="Cerrar imagen">Cerrar ×</button></div><img id="light-image" alt=""><p id="light-description" class="muted"></p></dialog>`}
function partners(){return head('colaboradores')+`<section class="section"><div class="wrap"><div class="grid">${content.partners.length?content.partners.map(x=>`<article class="card">${ContentStore.safeImage(x.image)?`<img src="${E(ContentStore.safeImage(x.image))}" alt="${E(x.title)}" style="width:100%;height:190px;object-fit:cover" loading="lazy">`:''}<div class="card-body">${ContentStore.safeImage(x.logo)?`<img class="logo" src="${E(ContentStore.safeImage(x.logo))}" alt="Logo de ${E(x.title)}">`:''}<span class="tag">${E(x.category)}</span><h3>${E(x.title)}</h3><p>${E(x.description)}</p>${x.address?`<p class="small">${E(x.address)}</p>`:''}${ContentStore.safeLink(x.url)?`<a href="${E(ContentStore.safeLink(x.url))}" target="_blank" rel="noopener noreferrer">Visitar sitio ↗</a>`:''}${x.email?`<p>${E(x.email)}</p>`:''}${x.phone?`<p>${E(x.phone)}</p>`:''}</div></article>`).join(''):partnerCategories()}</div><div class="callout"><div><h3>Visitas técnicas y colaboración con la escuela</h3><p class="muted">Un espacio abierto a estudios, empresas y proveedores que quieran acercar la práctica profesional al aula.</p></div><a class="btn" href="${link('contacto.html')}">Sumar mi empresa →</a></div></div></section>`}
function contact(){const s=content.settings;return head('contacto')+`<section class="section"><div class="wrap"><div class="home-top"><article class="card"><div class="card-body"><p class="eyebrow">Docencia y colaboración</p><h2>Sigamos en contacto</h2><p>Consultas sobre actividades, propuestas de visitas técnicas y participación en la red de colaboradores.</p>${/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email)?`<a class="btn" href="mailto:${E(s.email)}">Enviar correo ↗</a>`:'<p class="tag">Correo de contacto por incorporar</p>'}${ContentStore.safeLink(s.instagram)?`<p><a href="${E(ContentStore.safeLink(s.instagram))}" target="_blank" rel="noopener noreferrer">Visitar Instagram ↗</a></p>`:''}</div></article><aside class="card"><div class="card-body"><h3>${E(s.school)}</h3><p>${E(s.specialty)}</p><p>${E(s.siteName)}</p></div></aside></div></div></section>`}
async function init(){try{content=await ContentStore.seed();if(preview){try{content=await ContentStore.get()||content}catch{}}drawShell();document.title=(key==='inicio'?content.settings.siteName:content.pages[key].title)+' · '+content.settings.school;document.getElementById('main').innerHTML=key==='inicio'?home():key==='libro'?book():key==='calendario'?calendar():key==='galeria'?gallery():key==='colaboradores'?partners():key==='contacto'?contact():materials(key);const search=document.getElementById('search');if(search)search.addEventListener('input',()=>{let n=0;document.querySelectorAll('.searchable').forEach(x=>{x.hidden=!x.dataset.search.includes(search.value.toLowerCase());if(!x.hidden)n++});document.getElementById('search-empty').hidden=!!n});document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('.gallery-card').forEach(x=>{x.hidden=b.dataset.category!=='Todas'&&x.dataset.category!==b.dataset.category;if(!x.hidden)n++});document.getElementById('gallery-empty').hidden=!!n}));const dlg=document.getElementById('lightbox');if(dlg){document.getElementById('light-close').onclick=()=>dlg.close();dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const x=content.gallery.find(x=>x.id===b.dataset.image);document.getElementById('light-title').textContent=x.title;document.getElementById('light-image').src=ContentStore.safeImage(x.image);document.getElementById('light-image').alt=x.title;document.getElementById('light-description').textContent=x.description;dlg.showModal()})}}catch(e){document.getElementById('main').innerHTML=empty('No se pudo cargar la página',e.message)}}
init();
